// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;

    function setUp() public {
        c = new X_WALLET(address(new Log()));
    }

    function testFuzz_property(uint256 unlockSeed, uint256 amount) public {
        // Keep the fuzzed domain wide but avoid the collect-side guards.
        // Make the caller a fixed, funded account so that we always hit the unlock-time guard.
        address holder = address(0xBEEF);
        vm.deal(holder, 100 ether);

        // Deposit enough to pass MinSum (1 ether), with a fuzzed amount.
        uint256 putValue = 1 ether + (amount % 10 ether);
        vm.prank(holder);
        c.Put{value: putValue}(unlockSeed);

        // Read back the actually stored unlockTime (Put truncates to max(_unlockTime, block.timestamp)).
        (uint256 unlockTime, ) = c.Acc(holder);

        // Move time to EXACTLY the stored unlockTime; reference must reject, mutant accepts.
        vm.warp(unlockTime);

        // Collect exactly the deposited balance; other guards are satisfied.
        uint256 collectAmount = putValue;
        vm.prank(holder);
        c.Collect(collectAmount);

        // General rule: at block.timestamp == unlockTime the reference's strictly-greater guard
        // prevents Collect from reducing the holder's balance to zero, whereas the mutant does.
        (, uint256 balanceAfter) = c.Acc(holder);
        assertTrue(balanceAfter != 0);
    }
}
